INSERT INTO QuizData (quiz_id, type, question, level, choices, explanation, correctAnswer) VALUES
(1, 'ox', '전세는 매월 월세를 지불해야 하는 계약 형태이다.', '초급', '', '전세는 일정 금액의 보증금을 맡기고 매달 월세를 지불하지 않는 형태다.', 'x'),
(2, 'select', '다음 중 부동산 매매계약 시 반드시 포함되어야 할 사항은?', '초급', '매수자의 혈액형, 계약금액, 공인중개사의 취미', '계약금액은 매매계약의 핵심 요소 중 하나다.', 2),
(3, 'ox', '공시가격은 부동산 과세 기준 등에 활용되는 정부가 정한 가격이다.', '초급', '', '공시가격은 국토교통부 등이 산정하며, 세금 등의 기준으로 활용된다.', 'o'),
(4, 'select', '다음 중 임대차 계약 종료 후 세입자가 요구할 수 있는 권리는?', '중급', '양도소득세 면제, 보증금 반환, 건물 소유권 이전', '임대차 종료 시 세입자는 보증금 반환을 요구할 수 있다.', 2),
(5, 'ox', '재건축은 노후된 주택을 철거하고 새로 짓는 것을 의미한다.', '초급', '', '재건축은 안전진단 등을 거쳐 노후 건축물을 새로 짓는 사업이다.', 'o'),
(6, 'select', '부동산 등기부등본에서 확인할 수 없는 정보는?', '중급', '소유자 정보, 건물 구조, 근저당권 설정 여부', '등기부등본에는 건물 구조에 대한 정보는 포함되지 않는다.', 2),
(7, 'ox', '매매계약서에는 잔금 지급일이 반드시 명시되어야 한다.', '중급', '', '잔금일은 계약의 중요한 요소이며 명시되어야 한다.', 'o'),
(8, 'select', '다음 중 "분양권"의 의미로 적절한 것은?', '초급', '이미 완공된 아파트의 소유권, 건설 전 계약자의 권리, 임대차 계약 권리', '분양권은 미완공 건물에 대해 계약자가 갖는 권리이다.', 2),
(9, 'ox', '월세 계약 시 보증금을 설정할 수 없다.', '초급', '', '월세 계약에도 일반적으로 보증금을 설정한다.', 'x'),
(10, 'select', '다음 중 공인중개사가 해야 할 업무가 아닌 것은?', '중급', '계약 체결 중개, 등기 업무 대행, 거래 조건 설명', '등기 업무는 법무사가 담당하며 공인중개사의 업무가 아니다.', 2),
(11, 'ox', '근저당권이 설정된 부동산은 경매로 넘어갈 수 있다.', '중급', '', '채무불이행 시 근저당권자는 경매를 청구할 수 있다.', 'o'),
(12, 'select', '다음 중 전입신고의 효과로 올바른 것은?', '중급', '재산세 면제, 확정일자 부여, 대항력 발생', '전입신고와 확정일자는 세입자의 권리를 보호한다.', 3),
(13, 'ox', '분양가 상한제는 민간 아파트에는 적용되지 않는다.', '고급', '', '특정 조건에서는 민간 아파트에도 분양가 상한제가 적용된다.', 'x'),
(14, 'select', '다음 중 부동산 계약서 작성 시 가장 중요한 요소는?', '중급', '서명 날짜, 서명한 펜 색상, 중개업소 위치', '계약 효력 발생을 위해 서명 날짜는 필수적인 요소다.', 1),
(15, 'ox', '임대차 보호법은 상가 임차인에게는 적용되지 않는다.', '고급', '', '상가건물 임대차보호법이라는 별도 법이 존재한다.', 'x'),
(16, 'select', '다음 중 재개발 사업의 주된 목적은?', '초급', '건축 규제 강화, 지역 낙후 개선, 토지 세금 증대', '재개발은 노후 지역의 환경과 주거 여건을 개선하기 위한 것이다.', 2),
(17, 'ox', '등기부등본은 누구나 발급받을 수 있다.', '초급', '', '등기부등본은 공공정보로, 누구나 열람 및 발급이 가능하다.', 'o'),
(18, 'select', '다음 중 "대지권"에 대한 설명으로 올바른 것은?', '고급', '건물과 무관한 토지의 소유권, 아파트 지하실 전용권리, 건물에 딸린 토지 지분', '대지권은 아파트 등의 건물에 포함된 토지 지분을 의미한다.', 3),
(19, 'ox', '건축물대장은 건물의 구조, 용도, 면적 등의 정보를 담고 있다.', '초급', '', '건축물대장은 건물 관련 정보가 상세히 기재된 공적 장부이다.', 'o'),
(20, 'select', '다음 중 실거래가 공개 시스템의 주요 기능은?', '초급', '과거 아파트 광고 검색, 매물 등록, 실제 거래가격 확인', '실거래가 시스템은 실제 거래 가격을 확인할 수 있는 정부 서비스이다.', 3);
